int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;

    long long best = LLONG_MIN, cur = 0;
    int start = 0, bl = 0, br = 0;             // [bl, br] — najlepszy przedział
    for (int i = 0; i < n; i++) {
        if (cur <= 0) { cur = a[i]; start = i; } // poprzednia suma nie pomaga — zaczynamy od i
        else cur += a[i];
        if (cur > best) { best = cur; bl = start; br = i; }
    }
    cout << best << '\n' << bl + 1 << ' ' << br + 1 << '\n';   // numeracja od 1
}

long long kadaneMax(const vector<long long>& a) {
    long long best = LLONG_MIN, cur = 0;
    for (long long x : a) { cur = max(x, cur + x); best = max(best, cur); }
    return best;
}
long long kadaneMin(const vector<long long>& a) {
    long long best = LLONG_MAX, cur = 0;
    for (long long x : a) { cur = min(x, cur + x); best = min(best, cur); }
    return best;
}
long long maxCircular(const vector<long long>& a) {
    long long mx = kadaneMax(a);
    if (mx < 0) return mx;                         // same ujemne: nie wolno wziąć „pustego środka”
    long long total = accumulate(a.begin(), a.end(), 0LL);
    return max(mx, total - kadaneMin(a));          // zawinięty fragment = całość − najgorszy środek
}

long long maxRect(const vector<vector<long long>>& a) {
    int n = a.size(), m = a[0].size();
    long long best = LLONG_MIN;
    for (int top = 0; top < n; top++) {
        vector<long long> col(m, 0);               // col[j] = suma a[top..bot][j]
        for (int bot = top; bot < n; bot++) {
            for (int j = 0; j < m; j++) col[j] += a[bot][j];
            long long cur = 0;
            for (int j = 0; j < m; j++) {          // zwykły Kadane na col
                cur = max(col[j], cur + col[j]);
                best = max(best, cur);
            }
        }
    }
    return best;
}

