#include <bits/stdc++.h>
using namespace std;

long long bubbleSort(vector<int>& a) {            // zwraca liczbę zamian
    int n = a.size();
    long long swaps = 0;
    for (int i = 0; i < n - 1; i++) {
        bool zmiana = false;
        for (int j = 0; j < n - 1 - i; j++)       // największy „wypływa” na koniec
            if (a[j] > a[j + 1]) { swap(a[j], a[j + 1]); swaps++; zmiana = true; }
        if (!zmiana) break;                        // przejście bez zamian → posortowane
    }
    return swaps;
}

void insertionSort(vector<int>& a) {
    for (int i = 1; i < (int)a.size(); i++) {
        int x = a[i], j = i - 1;
        while (j >= 0 && a[j] > x) { a[j + 1] = a[j]; j--; }   // przesuń większe w prawo
        a[j + 1] = x;
    }
}

void selectionSort(vector<int>& a) {
    int n = a.size();
    for (int i = 0; i < n - 1; i++) {
        int mn = i;
        for (int j = i + 1; j < n; j++) if (a[j] < a[mn]) mn = j;
        swap(a[i], a[mn]);                          // co najwyżej n − 1 zamian
    }
}

int main() {
    vector<int> a = {5, 1, 4, 2, 8}, b = a, c = a;
    cout << "zamiany: " << bubbleSort(a) << '\n';   // 4 = liczba inwersji
    insertionSort(b);
    selectionSort(c);
    for (int x : b) cout << x << ' ';
    cout << '\n';
}

// p — permutacja liczb 0..n−1; element p[i] powinien trafić na pozycję p[i]
int minSwaps(const vector<int>& p) {
    int n = p.size(), cycles = 0;
    vector<bool> vis(n, false);
    for (int i = 0; i < n; i++) {
        if (vis[i]) continue;
        cycles++;
        for (int j = i; !vis[j]; j = p[j]) vis[j] = true;   // obejdź cały cykl
    }
    return n - cycles;                                       // cykl długości L naprawiamy L − 1 zamianami
}

