// sortuje pary (klucz, wartość) po kluczu, zachowując kolejność równych kluczy
vector<pair<int, int>> countingSort(const vector<pair<int, int>>& a, int K) {
    vector<int> pos(K + 1, 0);
    for (auto& e : a) pos[e.first + 1]++;
    for (int k = 0; k < K; k++) pos[k + 1] += pos[k];   // pos[k] = pierwsze miejsce dla klucza k
    vector<pair<int, int>> out(a.size());
    for (auto& e : a) out[pos[e.first]++] = e;           // w kolejności wejścia → stabilnie
    return out;
}

