// LSD radix sort: 4 stabilne zliczania po 8 bitów, od najmłodszego bajtu
void radixSort(vector<uint32_t>& a) {
    vector<uint32_t> buf(a.size());
    for (int shift = 0; shift < 32; shift += 8) {
        int cnt[257] = {0};
        for (uint32_t x : a) cnt[((x >> shift) & 255) + 1]++;
        for (int i = 0; i < 256; i++) cnt[i + 1] += cnt[i];
        for (uint32_t x : a) buf[cnt[(x >> shift) & 255]++] = x;
        a.swap(buf);                                        // wynik przebiegu wraca do a
    }
}

