#include <bits/stdc++.h>
using namespace std;

int n, LOG;
vector<int> bit;

void add(int i, int v) { for (; i <= n; i += i & -i) bit[i] += v; }
int kth(int k) {                                 // najmniejsze i, dla którego suma [1..i] = k
    int pos = 0;
    for (int pw = LOG; pw > 0; pw >>= 1)
        if (pos + pw <= n && bit[pos + pw] < k) { pos += pw; k -= bit[pos]; }
    return pos + 1;
}

int main() {
    long long k;
    cin >> n >> k;
    bit.assign(n + 1, 0);
    LOG = 1;
    while (LOG * 2 <= n) LOG *= 2;
    for (int i = 1; i <= n; i++) add(i, 1);       // wszyscy żyją
    long long pos = 0;                            // indeks (od 0) wśród żyjących, od którego liczymy
    for (int left = n; left > 0; left--) {
        pos = (pos + k - 1) % left;
        int who = kth(pos + 1);
        cout << who << (left > 1 ? ' ' : '\n');   // ostatni wypisany = ocalały
        add(who, -1);
    }
}

// numer ocalałego (1..n), co k-ta osoba odpada, liczymy od osoby nr 1
long long josephus(long long n, long long k) {
    long long r = 0;                              // J(1) = 0 (numeracja od 0)
    for (long long m = 2; m <= n; m++) r = (r + k) % m;
    return r + 1;
}

// k = 2: n = 2^m + L  →  ocalały 2L + 1
long long josephus2(long long n) {
    long long p = 1LL << __lg(n);                 // największa potęga dwójki ≤ n
    return 2 * (n - p) + 1;
}

// numeracja od 0; w jednym „okrążeniu” odpada ⌊n/k⌋ osób naraz
long long josephusBig(long long n, long long k) {
    if (n == 1) return 0;
    if (k == 1) return n - 1;
    if (k > n) return (josephusBig(n - 1, k) + k) % n;
    long long cnt = n / k;
    long long res = josephusBig(n - cnt, k);
    res -= n % k;
    if (res < 0) res += n;
    else res += res / (k - 1);
    return res;
}

