#include <bits/stdc++.h>
using namespace std;
typedef pair<long long, long long> P;              // przedział domknięty [l, r]

// 1) scalanie nachodzących (touch = true łączy też stykające się [1,3] i [4,5] na liczbach całkowitych)
vector<P> mergeIntervals(vector<P> v, bool touch = false) {
    sort(v.begin(), v.end());
    vector<P> res;
    for (auto [l, r] : v) {
        if (!res.empty() && l <= res.back().second + (touch ? 1 : 0))
            res.back().second = max(res.back().second, r);
        else
            res.push_back({l, r});
    }
    return res;
}

// 2) maksymalna liczba parami rozłącznych (wybór zajęć): sortuj po KOŃCU
int maxDisjoint(vector<P> v) {
    sort(v.begin(), v.end(), [](const P& a, const P& b) { return a.second < b.second; });
    int cnt = 0;
    long long lastEnd = LLONG_MIN;
    for (auto [l, r] : v)
        if (l > lastEnd) { cnt++; lastEnd = r; }   // dla [l, r) byłoby l >= lastEnd
    return cnt;
}

// 3) minimalna liczba punktów przebijających wszystkie przedziały
vector<long long> stabbingPoints(vector<P> v) {
    sort(v.begin(), v.end(), [](const P& a, const P& b) { return a.second < b.second; });
    vector<long long> pts;
    for (auto [l, r] : v)
        if (pts.empty() || pts.back() < l) pts.push_back(r);   // nieprzebity → punkt na jego końcu
    return pts;
}

// 4) minimalna liczba przedziałów pokrywających wszystkie liczby całkowite A..B; −1 = niemożliwe
int minCover(vector<P> v, long long A, long long B) {
    sort(v.begin(), v.end());                      // po początku
    int cnt = 0;
    size_t i = 0;
    long long cur = A;                             // pierwszy jeszcze niepokryty punkt
    while (cur <= B) {
        long long best = cur - 1;
        while (i < v.size() && v[i].first <= cur) best = max(best, v[i++].second);
        if (best < cur) return -1;                 // nikt nie pokrywa punktu cur
        cnt++;
        cur = best + 1;
    }
    return cnt;
}

int main() {
    vector<P> v = {{1, 3}, {2, 6}, {8, 10}, {9, 12}, {15, 18}};
    for (auto [l, r] : mergeIntervals(v)) cout << "[" << l << "," << r << "] ";
    cout << '\n';                                  // [1,6] [8,12] [15,18]
    cout << maxDisjoint(v) << '\n';                // 3
    for (long long p : stabbingPoints(v)) cout << p << ' ';
    cout << '\n';                                  // 3 10 18
    cout << minCover({{1, 4}, {2, 7}, {5, 10}, {8, 12}}, 1, 12) << '\n';   // 3
}

struct Iv { long long l, r, w; };                  // przedział domknięty [l, r] z wagą w
long long weightedSchedule(vector<Iv> v) {
    sort(v.begin(), v.end(), [](const Iv& a, const Iv& b) { return a.r < b.r; });
    int n = v.size();
    vector<long long> ends(n), dp(n + 1, 0);       // dp[i] = najlepszy wynik z pierwszych i przedziałów
    for (int i = 0; i < n; i++) ends[i] = v[i].r;
    for (int i = 0; i < n; i++) {
        int j = lower_bound(ends.begin(), ends.end(), v[i].l) - ends.begin();   // ile kończy się przed l
        dp[i + 1] = max(dp[i], dp[j] + v[i].w);
    }
    return dp[n];
}

