struct MedianSet {
    multiset<long long> L, R;
    void fix() {
        if (L.size() > R.size() + 1) { R.insert(*L.rbegin()); L.erase(prev(L.end())); }
        else if (R.size() > L.size()) { L.insert(*R.begin()); R.erase(R.begin()); }
