#include <bits/stdc++.h>
using namespace std;

int main() {
    string text = "abracadabra";
    map<char, long long> freq;
    for (char c : text) freq[c]++;
    vector<int> L, R;                           // dzieci węzła (−1 = liść)
    vector<char> sym;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    for (auto [c, f] : freq) {
        pq.push({f, (int)sym.size()});
        sym.push_back(c); L.push_back(-1); R.push_back(-1);
    }
    while (pq.size() > 1) {
        auto [fa, a] = pq.top(); pq.pop();      // kopie (nie referencje!) przed pop
        auto [fb, b] = pq.top(); pq.pop();
        pq.push({fa + fb, (int)sym.size()});
        sym.push_back(0); L.push_back(a); R.push_back(b);
    }
    map<char, string> code;
    auto dfs = [&](auto& self, int v, string cur) -> void {
        if (L[v] == -1) { code[sym[v]] = cur.empty() ? "0" : cur; return; }   // jedna litera → kod "0"
        self(self, L[v], cur + '0');
        self(self, R[v], cur + '1');
    };
    dfs(dfs, pq.top().second, "");
    long long bits = 0;
    for (auto [c, s] : code) {
        cout << c << ": " << s << '\n';
        bits += freq[c] * (long long)s.size();
    }
    cout << "bitow: " << bits << '\n';          // 23
}

long long huffmanSorted(const vector<long long>& w) {     // w posortowane rosnąco
    queue<long long> a, b;                                 // a — wejście, b — sumy (rosną!)
    for (long long x : w) a.push(x);
    auto takeMin = [&]() {
        long long x;
        if (b.empty() || (!a.empty() && a.front() <= b.front())) { x = a.front(); a.pop(); }
        else { x = b.front(); b.pop(); }
        return x;
    };
    long long cost = 0;
    while (a.size() + b.size() > 1) {
        long long x = takeMin();
        long long y = takeMin();
        cost += x + y;
        b.push(x + y);
    }
    return cost;
}

