#include <bits/stdc++.h>
using namespace std;

bool przestepny(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }

int dniWMiesiacu(int y, int m) {
    static const int d[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    return d[m - 1] + (m == 2 && przestepny(y));
}

// ile dni minęło od 1.01.0001 (kalendarz gregoriański rozciągnięty wstecz)
long long numerDnia(int y, int m, int d) {
    long long n = 365LL * (y - 1) + (y - 1) / 4 - (y - 1) / 100 + (y - 1) / 400;
    for (int i = 1; i < m; i++) n += dniWMiesiacu(y, i);
    return n + d - 1;
}

// odwrotność: numer dnia → data
void dataZNumeru(long long N, int& y, int& m, int& d) {
    y = N / 366 + 1;                                 // przybliżenie z dołu
    while (numerDnia(y + 1, 1, 1) <= N) y++;
    long long r = N - numerDnia(y, 1, 1);            // dzień roku liczony od 0
    m = 1;
    while (r >= dniWMiesiacu(y, m)) { r -= dniWMiesiacu(y, m); m++; }
    d = r + 1;
}

// 0 = poniedziałek, ..., 6 = niedziela (1.01.0001 to poniedziałek)
int dzienTygodnia(int y, int m, int d) { return numerDnia(y, m, d) % 7; }

int main() {
    const char* nazwy[] = {"poniedzialek", "wtorek", "sroda", "czwartek", "piatek", "sobota", "niedziela"};
    int d1, m1, y1, d2, m2, y2;
