    printf("roznica: %lld dni\n", numerDnia(y2, m2, d2) - numerDnia(y1, m1, d1));
    printf("%02d.%02d.%04d to %s\n", d1, m1, y1, nazwy[dzienTygodnia(y1, m1, d1)]);
    int y, m, d;
    dataZNumeru(numerDnia(y1, m1, d1) + 100, y, m, d);
    printf("za 100 dni: %02d.%02d.%04d\n", d, m, y);
}

// Sakamoto: 0 = niedziela, 1 = poniedziałek, ..., 6 = sobota
int sakamoto(int y, int m, int d) {
    static const int t[] = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4};
    if (m < 3) y -= 1;
    return (y + y / 4 - y / 100 + y / 400 + t[m - 1] + d) % 7;
}

// Zeller: 0 = sobota, 1 = niedziela, 2 = poniedziałek, ..., 6 = piątek
int zeller(int y, int m, int d) {
    if (m < 3) { m += 12; y -= 1; }       // styczeń i luty = 13. i 14. miesiąc poprzedniego roku
    int K = y % 100, J = y / 100;
    return (d + 13 * (m + 1) / 5 + K + K / 4 + J / 4 + 5 * J) % 7;
}

